      SUBROUTINE PUNCH1CC     PUNCHES FIRST-ORDER TRANSFER MATRICES ONTO "CARDS"CC ----------------------------------------------------------------------      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RS.CIN'CC     LOCAL VARIABLESC      INTEGER         J, K      REAL            OUTPUT(30)C ---------------------------------------------------------------------CC     CALCULATE TRANSFER MATRICESC      CALL RCALCCC     PUNCH FIRST ORDER MATRIXC      DO 2 J = 1, 6      DO 1 K = 1, 6      OUTPUT(K) = RS(J,K)*UBEAM(K)/UBEAM(J)    1 CONTINUE      WRITE (NPUNCH,1003) J, (OUTPUT(K), K = 1, 6) 1003 FORMAT (7H  FIRST, I5, 6(1PE11.3))    2 CONTINUECC     PUNCH SECOND ORDER MATRIX ELEMENTSC      IF (NORD3 .GE. 2) CALL PUNCH2      RETURN      END